\begin{frontmatter}

\title{Spectral Reconstruction in Fractional Derivative Order}

\author{Derek C. Braun}
\address{School of Science, Technology, Accessibility, Mathematics and Public Health, Gallaudet University, Washington, DC 20002, USA}
\ead{derek.braun@gallaudet.edu}

\begin{abstract}
We introduce the spectral reconstruction operator $\mathcal{S}$, which treats derivative order as a continuous variable and integrates fractional derivative data across all nonnegative real orders to represent analytic functions. Because the fractional derivatives in the integrand draw on function values across an infinite stretch of the real line, the spectral integrand encodes information about $f$ that no individual integer derivative at the origin can capture. We define an admissible class of fractional derivative families that recover the classical derivative ladder, satisfy the semigroup property, and keep $D^r f(0)$ finite (a condition that excludes monomials). We prove that the spectral reconstruction operator asymptotically reconstructs the exponential function as $x\to\infty$. We further show that the spectral operator and the classical Maclaurin series are formed from the same underlying function of derivative order: the spectral operator integrates it continuously, while the Maclaurin series samples it at the nonnegative integers. Classical summation formulas therefore quantify this discrepancy under their respective hypotheses. Under their respective hypotheses, the Euler--Maclaurin formula gives an exact identity consisting of a finite correction series and its remainder, while the Abel--Plana formula gives an exact correction integral. Examples drawn from entire, oscillatory, rapidly decaying, special-function, and finite-radius analytic classes demonstrate stable reconstruction within their applicable domains. The Abel--Plana representation matches $f$ to the full precision of our computations in every case. In the finite-radius examples studied here, one with a real pole and one with a complex-conjugate pole pair, the spectral integral and the Maclaurin series encounter the same convergence boundary, although through different mathematics. In the examples studied, the sum--integral discrepancy remains bounded, so the uncorrected operator provides useful approximations where $f(x)$ is large. The leading summation term $\mathcal{E}_0=\frac{1}{2}f(0)$ and higher terms then systematically account for the discrepancy concentrated near the origin. These results establish derivative order as a meaningful, non-local continuous domain for the representation and reconstruction of analytic functions.
\end{abstract}

\begin{keyword}
fractional calculus \sep
fractional derivatives \sep
Liouville derivative \sep
reconstruction operator \sep
analytic function reconstruction \sep
Euler--Maclaurin formula \sep
Abel--Plana formula
\end{keyword}
\end{frontmatter}

\label{sec:operator}
We now give this construction its formal definition: an integral over fractional derivative order that replaces the discrete sum of the classical Maclaurin series.

\begin{definition}
Let $D^{r}f(0)$ denote an admissible extension of the integer-order derivative data to real order $r\geq 0$. For real $x>0$ such that the integral converges, the \textit{spectral reconstruction operator} is
\begin{equation}
\label{eq:operator_def}
\mathcal{S}[f](x)
:=
\int_{0}^{\infty}
\frac{D^{r}f(0)\,x^{r}}{\Gamma(r+1)}
\,dr.
\end{equation}
The operator therefore depends on the chosen non-integer-order extension, which the admissibility conditions of Section~\ref{sub:frac_deriv_admissibility} specify.
\end{definition}

\textbf{Fractional derivative}. For the exponential function, we use the left-sided Liouville derivative based at $-\infty$, which gives
\[
\prescript{\mathrm{L}}{-\infty}{D}^{r} e^{x}=e^{x},
\qquad\text{so that}\qquad
\prescript{\mathrm{L}}{-\infty}{D}^{r} e^{x}\big|_{x=0} = 1.
\]
\textbf{Correction terms}. The integrand simplifies to
\[
\phi(r,x) = \frac{x^{r}}{\Gamma(r+1)}.
\]
From Definition~\ref{def:correction_series}, the first three correction terms are:

\[
\mathcal{E}_{\leq 2}[e^{x}](x)
=
\underbracket{\frac{1}{2}}_{\textstyle \mathcal{E}_0}
\;+\;
\underbracket{- \frac{1}{12}\,(\log x + \gamma)}_{\textstyle \mathcal{E}_1}
\;+\;
\underbracket{\frac{1}{720}
     \!\left[(\log x+\gamma)^{3}
             - \frac{\pi^{2}}{2}(\log x+\gamma)
             + 2\zeta(3)\right]}_{\textstyle \mathcal{E}_2}
\;+\;
\cdots.
\]
Figure~\ref{fig:exponential} compares the uncorrected reconstruction, the common endpoint correction, and the fixed Euler--Maclaurin refinement $\mathcal E_{\leq 2}$.

\textbf{Fractional derivative}. For the sine function, the Liouville (Fourier-multiplier) definition is admissible and yields the phase-shift result below.
\[
{}^{\mathrm{L}}_{\mathbb{R}}D^{r} \sin x
= \sin\!\left(x + \frac{\pi r}{2}\right),
\qquad\text{so that}\qquad
{}^{\mathrm{L}}_{\mathbb{R}}D^{r} \sin x \big|_{x=0}
= \sin\!\left(\frac{\pi r}{2}\right).
\]
\textbf{Correction terms}. The integrand simplifies to
\[
\phi(r,x) = \sin\!\left(\frac{\pi r}{2}\right)\frac{x^{r}}{\Gamma(r+1)}.
\]
From Definition~\ref{def:correction_series}, the first three correction terms are:
\[
\begin{aligned}
\mathcal{E}_{\leq 2}[\sin](x)
={}&
\underbracket{0}_{\textstyle \mathcal{E}_0}
\;+\;
\underbracket{-\frac{\pi}{24}}_{\textstyle \mathcal{E}_1}
\;+\;
\underbracket{\frac{\pi}{1920}\!\left(4(\log x+\gamma)^{2}-\pi^{2}\right)}_{\textstyle \mathcal{E}_2}
\;+\;
\cdots.
\end{aligned}
\]

The vanishing of $\mathcal E_0$ reflects the common endpoint formula $\mathcal E_0=\frac12 f(0)$.

